INSERT INTO "courses" ("id", "name", "description", "subject_id", "teacher_id", "semester_number", "faculty_id", "kafedra_id", "speciality_id") VALUES
  (1, 'Konchilik ishi asoslari', 'Konchilik ishi asoslari — konchilik ishi yoʻnalishi talabalari uchun 1-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 1, 4, 1, 1, 1, 1),
  (2, 'Ochiq konchilik ishlari', 'Ochiq konchilik ishlari — konchilik ishi yoʻnalishi talabalari uchun 3-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 2, 4, 3, 1, 1, 1),
  (3, 'Geodeziya', 'Geodeziya — geodeziya va geoinformatika yoʻnalishi talabalari uchun 1-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 5, 9, 1, 1, 2, 2),
  (4, 'Markshayderlik ishi', 'Markshayderlik ishi — geodeziya va geoinformatika yoʻnalishi talabalari uchun 4-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 6, 6, 4, 1, 2, 2),
  (5, 'Umumiy geologiya', 'Umumiy geologiya — geologiya, qidiruv va konlar geologiyasi yoʻnalishi talabalari uchun 1-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 8, 12, 1, 1, 3, 3),
  (6, 'Mineralogiya va petrografiya', 'Mineralogiya va petrografiya — geologiya, qidiruv va konlar geologiyasi yoʻnalishi talabalari uchun 3-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 9, 10, 3, 1, 3, 3),
  (7, 'Metallurgiya nazariyasi', 'Metallurgiya nazariyasi — metallurgiya yoʻnalishi talabalari uchun 2-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 11, 17, 2, 2, 4, 4),
  (8, 'Rangli metallar metallurgiyasi', 'Rangli metallar metallurgiyasi — metallurgiya yoʻnalishi talabalari uchun 5-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 12, 17, 5, 2, 4, 4),
  (9, 'Umumiy kimyo', 'Umumiy kimyo — kimyoviy texnologiya yoʻnalishi talabalari uchun 1-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 13, 21, 1, 2, 5, 5),
  (10, 'Fizik kimyo', 'Fizik kimyo — kimyoviy texnologiya yoʻnalishi talabalari uchun 3-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 14, 20, 3, 2, 5, 5),
  (11, 'Elektrotexnika nazariy asoslari', 'Elektrotexnika nazariy asoslari — elektr energetikasi yoʻnalishi talabalari uchun 2-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 16, 26, 2, 3, 6, 6),
  (12, 'Elektr mashinalari', 'Elektr mashinalari — elektr energetikasi yoʻnalishi talabalari uchun 5-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 17, 25, 5, 3, 6, 6),
  (13, 'Nazariy mexanika', 'Nazariy mexanika — texnologik mashinalar va jihozlar yoʻnalishi talabalari uchun 2-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 19, 28, 2, 3, 7, 7),
  (14, 'Mashina detallari', 'Mashina detallari — texnologik mashinalar va jihozlar yoʻnalishi talabalari uchun 4-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 20, 28, 4, 3, 7, 7),
  (15, 'Axborot texnologiyalari', 'Axborot texnologiyalari — axborot tizimlari va texnologiyalari yoʻnalishi talabalari uchun 1-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 23, 37, 1, 4, 9, 8),
  (16, 'Maʼlumotlar bazasi', 'Maʼlumotlar bazasi — axborot tizimlari va texnologiyalari yoʻnalishi talabalari uchun 3-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 24, 38, 3, 4, 9, 8),
  (17, 'Dasturlash asoslari', 'Dasturlash asoslari — dasturiy injiniring yoʻnalishi talabalari uchun 1-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 27, 41, 1, 4, 10, 9),
  (18, 'Obyektga yoʻnaltirilgan dasturlash', 'Obyektga yoʻnaltirilgan dasturlash — dasturiy injiniring yoʻnalishi talabalari uchun 3-semestr kursi. Video darslar, ma''ruza matnlari va amaliy topshiriqlar.', 28, 42, 3, 4, 10, 9);
